export const SummaryOutputSchema = {};
export const FindOrderInputSchema = {};
export const FindOrderOutputSchema = {};

import { agentTool } from 'agents/agent-tools';
import { tool } from 'ai';
import { SummaryAgent } from './agents.js';
import { FindOrderInputSchema, FindOrderOutputSchema } from './contracts.js';
import { findOrder } from './implementations.js';
export const findOrderTool = tool({ inputSchema: FindOrderInputSchema, outputSchema: FindOrderOutputSchema, execute: findOrder });
export const summaryHandoffTool = agentTool(SummaryAgent, { description: 'Summarizes a support request.' });

import { AIChatAgent } from '@cloudflare/ai-chat';
import { Think } from '@cloudflare/think';
import { Output, streamText } from 'ai';
import { SummaryOutputSchema } from './contracts.js';
import { loadSummaryInstruction, loadSupportInstruction } from './instructions.js';
import { findOrderTool, summaryHandoffTool } from './tools.js';
export class SupportAgent extends Think { getSystemPrompt() { return loadSupportInstruction(); } getTools() { return { find_order: findOrderTool, summarize: summaryHandoffTool }; } }
export class SummaryAgent extends AIChatAgent { onChatMessage(onFinish, options?) { return streamText({ instructions: loadSummaryInstruction(), output: Output.object({ schema: SummaryOutputSchema }), tools: { find_order: findOrderTool } }); } }
